void handle_write(char *filename, char *sent_idx_str) {
    int sent_idx = atoi(sent_idx_str);

    // reset signal handling variables
    current_locked_sentence = -1;   
    current_locked_filename[0] = '\0';

    // Get SS info from NM
    Message msg;
    init_message(&msg);
    msg.type = MSG_WRITE;
    strcpy(msg.sender, client.username);
    strcpy(msg.filename, filename);

    if (send_message(client.nm_sock, &msg) < 0) {
        printf("Error: Lost connection to Name Server\n");
        return;
    }

    Message response;
    if (recv_message(client.nm_sock, &response) < 0) {
        printf("Error: No response from Name Server\n");
        return;
    }

    if (response.status != SUCCESS) {
        print_error(response.status);
        return;
    }

    // Connect to SS
    int ss_sock = connect_to_ss(response.data);
    if (ss_sock < 0) {
        printf("Error: Could not connect to storage server\n");
        return;
    }

    current_ss_sock = ss_sock;

    // Lock sentence
    init_message(&msg);
    msg.type = MSG_LOCK_SENTENCE;
    strcpy(msg.filename, filename);
    strcpy(msg.sender, client.username);
    msg.sentence_index = sent_idx;

    if (send_message(ss_sock, &msg) < 0 || recv_message(ss_sock, &response) < 0) {
        printf("Error: Could not lock sentence (connection issue)\n");
        close(ss_sock);
        current_ss_sock = -1;
        return;
    }

    if (response.status != SUCCESS) {
        print_error(response.status);
        close(ss_sock);
        current_ss_sock = -1;
        return;
    }

    // For signal handling
    current_locked_sentence = sent_idx; 
    strncpy(current_locked_filename, filename, MAX_FILENAME - 1);
    current_locked_filename[MAX_FILENAME - 1] = '\0';

    printf("Sentence locked. Enter writes (word_index content), then type ETIRW:\n");

    // Local buffer for pending writes
    typedef struct { int word_idx; char *content; } PendingWrite;
    PendingWrite *pending = NULL;
    int pending_count = 0, pending_cap = 0;
    auto add_pending = [&](int widx, const char *c) {
        if (pending_count + 1 > pending_cap) {
            int ncap = pending_cap ? pending_cap * 2 : 8;
            PendingWrite *tmp = realloc(pending, sizeof(PendingWrite) * ncap);
            if (!tmp) return -1;
            pending = tmp;
            pending_cap = ncap;
        }
        pending[pending_count].word_idx = widx;
        pending[pending_count].content = strdup(c);
        pending_count++;
        return 0;
    };
    auto free_pending = [&]() {
        for (int i = 0; i < pending_count; i++) free(pending[i].content);
        free(pending);
        pending = NULL;
        pending_count = 0;
        pending_cap = 0;
    };

    // Read write commands and buffer them locally
    char line[MAX_BUFFER];
    int write_count = 0;
    int status_ok = 1;

    while (1) {
        printf("Client: ");
        if (!fgets(line, sizeof(line), stdin)) {
            if(sigint_received) {
                perform_pending_unlock();
                free_pending();
                printf("\nInterrupted; exiting client.\n");
                exit(0);
            }
            break;
        }

        // Check for signal during input
        if(sigint_received) {
            perform_pending_unlock();
            free_pending();
            printf("\nInterrupted; exiting client.\n");
            exit(0);
        }

        trim_whitespace(line);

        if (strcmp(line, "ETIRW") == 0) {
            break; // commit buffered writes
        }

        // Parse word_index and content
        int word_idx;
        char content[MAX_BUFFER];

        if (sscanf(line, "%d %[^\n]", &word_idx, content) != 2) {
            printf("Invalid format. Use: <word_index> <content>\n");
            continue;
        }

        if (add_pending(word_idx, content) != 0) {
            printf("Error: Out of memory buffering writes\n");
            free_pending();
            status_ok = 0;
            break;
        }
    }

    // If nothing buffered, just unlock and exit
    if (pending_count == 0) {
        // Unlock sentence if we still have a connection
        init_message(&msg);
        msg.type = MSG_UNLOCK_SENTENCE;
        strcpy(msg.filename, filename);
        strcpy(msg.sender, client.username);
        msg.sentence_index = sent_idx;

        if (send_message(ss_sock, &msg) < 0 || recv_message(ss_sock, &response) < 0) {
            printf("Warning: Could not send/receive unlock (connection may be lost)\n");
        } else if (response.status != SUCCESS) {
            printf("Unlock failed: ");
            print_error(response.status);
        }

        close(ss_sock);
        current_ss_sock = -1;
        current_locked_sentence = -1;
        current_locked_filename[0] = '\0';
        free_pending();
        printf("No writes performed.\n");
        return;
    }

    // Commit phase: send buffered writes to SS (keep existing retry logic per write)
    for (int i = 0; i < pending_count && status_ok; i++) {
        int retry_count = 0;
        int write_success = 0;

        while (retry_count < 5 && !write_success) {
            init_message(&msg);
            msg.type = MSG_WRITE;
            strcpy(msg.filename, filename);
            strcpy(msg.sender, client.username);
            msg.sentence_index = sent_idx;
            msg.word_index = pending[i].word_idx;
            strncpy(msg.data, pending[i].content, MAX_BUFFER - 1);
            msg.data[MAX_BUFFER - 1] = '\0';

            if (send_message(ss_sock, &msg) < 0) {
                // Send failed - connection lost
                printf("Error: Storage server disconnected during write\n");
                printf("Attempting to reconnect (attempt %d/5)...\n", retry_count + 1);
                close(ss_sock);
                current_ss_sock = -1;
                retry_count++;

                // Re-query NM for SS info
                init_message(&msg);
                msg.type = MSG_WRITE;
                strcpy(msg.sender, client.username);
                strcpy(msg.filename, filename);

                if (send_message(client.nm_sock, &msg) < 0) { printf("Error: NM unreachable\n"); continue; }
                if (recv_message(client.nm_sock, &response) < 0) { printf("Error: NM no response\n"); continue; }
                if (response.status != SUCCESS) { printf("Error: NM returned SS unavailable\n"); continue; }

                ss_sock = connect_to_ss(response.data);
                if (ss_sock < 0) { printf("Reconnect failed\n"); continue; }
                current_ss_sock = ss_sock;
            }

            // If send succeeded (or we reconnected), try to receive response
            if (recv_message(ss_sock, &response) < 0) {
                // recv failed: treat as transient and retry
                printf("Error: No response from SS (attempt %d)\n", retry_count + 1);
                close(ss_sock);
                current_ss_sock = -1;
                retry_count++;

                // Try to get new SS info before retrying
                init_message(&msg);
                msg.type = MSG_WRITE;
                strcpy(msg.sender, client.username);
                strcpy(msg.filename, filename);
                if (send_message(client.nm_sock, &msg) < 0 || recv_message(client.nm_sock, &response) < 0) {
                    continue;
                }
                if (response.status != SUCCESS) continue;
                ss_sock = connect_to_ss(response.data);
                if (ss_sock < 0) continue;
                current_ss_sock = ss_sock;
                continue;
            }

            if (response.status != SUCCESS) {
                // Non-connection error; abort commit
                printf("Write failed: ");
                print_error(response.status);
                status_ok = 0;
                break;
            }

            // succeeded
            write_success = 1;
            write_count++;
        } // end retry loop

        if (!write_success) {
            printf("Error: Could not complete a write after retries; aborting remaining writes\n");
            status_ok = 0;
            break;
        }
    } // end for each pending write

    // Unlock sentence if we still have a connection
    if (current_ss_sock > 0) {
        init_message(&msg);
        msg.type = MSG_UNLOCK_SENTENCE;
        strcpy(msg.filename, filename);
        strcpy(msg.sender, client.username);
        msg.sentence_index = sent_idx;

        if (send_message(ss_sock, &msg) < 0) {
            printf("Error: Could not send unlock (connection lost)\n");
        } else if (recv_message(ss_sock, &response) < 0) {
            printf("Error: Could not receive unlock response (connection lost)\n");
        } else if (response.status != SUCCESS) {
            printf("Unlock failed: ");
            print_error(response.status);
        }

        close(ss_sock);
    }

    // Clear signal handling variables
    current_ss_sock = -1;
    current_locked_sentence = -1;
    current_locked_filename[0] = '\0';

    free_pending();

    // Print final status
    if (write_count > 0 && status_ok) {
        printf("All writes completed successfully! (%d write(s))\n", write_count);
    } else if (write_count == 0) {
        printf("No writes performed.\n");
    } else {
        printf("Write session ended with errors. Completed %d write(s) before failure.\n", write_count);
    }
}
