// NEW: insert_raw_in_sentence - insert the exact string 'raw' as a single token
int insert_raw_in_sentence(FileContent *fc, int sent_idx, int word_idx, const char *raw) {
    if (!fc || !raw) return -1;

    // Allow appending a new sentence index (same logic as insert_word_in_sentence)
    if (sent_idx < 0 || sent_idx > fc->sentence_count) {
        log_formatted(LOG_ERROR, "Invalid sentence index: %d (file has %d sentences)", 
                     sent_idx, fc->sentence_count);
        return -1;
    }

    if (sent_idx == fc->sentence_count) {
        // allocate new sentence slot
        if (fc->sentence_count >= fc->capacity) {
            int newcap = fc->capacity ? fc->capacity * 2 : 10;
            Sentence *tmp = realloc(fc->sentences, sizeof(Sentence) * newcap);
            if (!tmp) {
                log_formatted(LOG_ERROR, "Out of memory expanding sentences");
                return -1;
            }
            fc->sentences = tmp;
            fc->capacity = newcap;
        }
        fc->sentences[fc->sentence_count].capacity = 10;
        fc->sentences[fc->sentence_count].word_count = 0;
        fc->sentences[fc->sentence_count].words = malloc(sizeof(char*) * fc->sentences[fc->sentence_count].capacity);
        if (!fc->sentences[fc->sentence_count].words) {
            log_formatted(LOG_ERROR, "Out of memory allocating words for new sentence");
            return -1;
        }
        fc->sentence_count++;
    }

    Sentence *sent = &fc->sentences[sent_idx];

    // word_idx is 1-based
    if (word_idx < 1 || word_idx > sent->word_count + 1) {
        log_formatted(LOG_ERROR, "Invalid word index: %d (sentence has %d words, valid range: 1-%d)", 
                     word_idx, sent->word_count, sent->word_count + 1);
        return -1;
    }

    int actual_idx = word_idx - 1;

    // Ensure capacity for new word
    if (sent->word_count + 1 > sent->capacity) {
        while (sent->capacity < sent->word_count + 1) sent->capacity *= 2;
        char **tmp = realloc(sent->words, sizeof(char*) * sent->capacity);
        if (!tmp) {
            log_formatted(LOG_ERROR, "Out of memory expanding words");
            return -1;
        }
        sent->words = tmp;
    }

    // Shift words to make room
    for (int j = sent->word_count; j > actual_idx; j--) {
        sent->words[j] = sent->words[j - 1];
    }

    // Insert the raw token (preserve exact string)
    sent->words[actual_idx] = strdup(raw);
    if (!sent->words[actual_idx]) {
        log_formatted(LOG_ERROR, "Out of memory duplicating raw string");
        return -1;
    }
    sent->word_count++;

    return 0; // raw insertion does not create new sentences
}

// TWEAK: avoid inserting an extra separating space when token already contains spaces.
// This preserves client's internal spacing for raw tokens while keeping old behaviour for normal tokens.
int write_file_content(const char *filepath, FileContent *fc) {
    FILE *file = fopen(filepath, "w");
    if (!file) return -1;

    for (int i = 0; i < fc->sentence_count; i++) {
        for (int j = 0; j < fc->sentences[i].word_count; j++) {
            char *token = fc->sentences[i].words[j];
            if (!token) continue;
            fprintf(file, "%s", token);

            if (j < fc->sentences[i].word_count - 1) {
                int cur_is_delim = is_delimiter(token[0]);
                int next_is_delim = is_delimiter(fc->sentences[i].words[j + 1][0]);
                // If current token already contains whitespace, don't add an extra space.
                int token_has_space = (strchr(token, ' ') != NULL) || (strchr(token, '\t') != NULL);
                if (!token_has_space && !cur_is_delim && !next_is_delim) {
                    fprintf(file, " ");
                }
            }
        }

        if (i < fc->sentence_count - 1) {
            fprintf(file, " ");
        }
    }

    fclose(file);
    return 0;
}

